def bars3(vals, labels, colors, w=1000):
    mx = max(vals)
    b = ''
    for i, (v, l, c) in enumerate(zip(vals, labels, colors)):
        x = 90 + i * 300
        h = 150 * v / mx
        b += rect(x, 175 - h, 190, h, c, 12) + T(x + 95, 168 - h, v, 30, NAVY) + T(x + 95, 210, l, 26, NAVY)
    return svg(w, 230, b, '26vh')


